<?php
namespace App\Services;use App\Models\ConnectorSecret;use RuntimeException;final class ConnectorSecretResolver{public function get(string $organizationId,string $name):string{$secret=ConnectorSecret::where('organization_id',$organizationId)->where('name',$name)->first();if(!$secret)throw new RuntimeException("Connector secret '{$name}' not found");return $secret->secret_encrypted;}public function headers(string $organizationId,array $headers,array $secretHeaders=[]):array{foreach($secretHeaders as $header=>$name)$headers[$header]=$this->get($organizationId,(string)$name);return $headers;}}
